# Let me analyze by looking at non-3 cells first - do those change?
def analyze_transformations(name, inp, out):
    """Find which cells change."""
    h = len(inp)
    changes = {}
    for i in range(h):
        for j in range(len(inp[0])):
            if inp[i][j] != out[i][j]:
                val_in = inp[i][j]
                if val_in not in changes:
                    changes[val_in] = []
                changes[val_in].append((i, j, out[i][j]))
    return changes

