# Apply the rule to Test input
test_in = G['Test input']
h, w = len(test_in), len(test_in[0])

def transform_grid(grid):
    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                h_mirror_c = w - 1 - c
                if grid[r][h_mirror_c] != 3:
                    result[r][c] = grid[r][h_mirror_c]
                else:
                    v_mirror_r = h - 1 - r
                    result[r][c] = grid[v_mirror_r][c]
    return result

